DELIMITER ;;
CREATE DEFINER=`Mark`@`localhost` PROCEDURE `new_procedure`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE museumCode VARCHAR(50);
    DECLARE curDate DATE;
    DECLARE endDate DATE;
    DECLARE museumCursor CURSOR FOR SELECT `code` FROM `museums`;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- Отключаем safe updates на время работы процедуры
    SET SQL_SAFE_UPDATES = 0;

    -- Все операции в транзакции для целостности
    START TRANSACTION;

    -- 1. Удаляем все прошедшие слоты (раньше сегодняшнего дня)
    DELETE FROM `time_slots` WHERE `date` < CURDATE();

    -- Устанавливаем период: от сегодня до +90 дней
    SET curDate = CURDATE();
    SET endDate = CURDATE() + INTERVAL 90 DAY;

    OPEN museumCursor;

    read_loop: LOOP
        FETCH museumCursor INTO museumCode;
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- Генерируем слоты для всех дней диапазона
        WHILE curDate <= endDate DO
            INSERT IGNORE INTO `time_slots` 
                (`museum_code`, `date`, `start_time`, `end_time`, `available_tickets`)
            VALUES
                (museumCode, curDate, '10:00:00', '12:00:00', 10),
                (museumCode, curDate, '12:00:00', '14:00:00', 10),
                (museumCode, curDate, '14:00:00', '16:00:00', 10),
                (museumCode, curDate, '16:00:00', '18:00:00', 10);

            SET curDate = DATE_ADD(curDate, INTERVAL 1 DAY);
        END WHILE;

        -- Сброс даты для следующего музея
        SET curDate = CURDATE();
    END LOOP;

    CLOSE museumCursor;

    COMMIT;

    -- Возвращаем safe updates в исходное состояние
    SET SQL_SAFE_UPDATES = 1;

END ;;
